type Lesson = [intro: string, keyIdea: string, example: string, question: string, answer: string];
const orders = new Map<string, number>();
function U(subject: SchoolSubjectId, grade: SchoolGrade, slug: string, section: string, title: string, pages: number[], topics: string[], lesson: Lesson, notes?: string): SchoolUnit {
 const key = `${subject}-${grade}`; const order = (orders.get(key) ?? 0) + 1; orders.set(key, order);
 const sourceId = subject === 'social' ? 'frp-social-transition-2026' : subject === 'project' ? 'fgos-project-requirements' : `frp-${subject}-${grade < 10 ? '5-9' : '10-11'}-2025`;
 return { id: `program-${subject}-${grade}-${slug}`, subject, grade, order, section, title, topics, sourceId, pages, objectives: [lesson[1]], intro: lesson[0], keyIdea: lesson[1], example: lesson[2], question: lesson[3], answer: lesson[4], visual: subject === 'russian' || subject === 'english' ? 'syntax' : subject === 'history' ? 'history' : 'concept', ...(notes ? { notes } : {}) };
}
